// A second pointer must never move or commit the first pointer's Canvas gesture.
vm.runInContext("canvasGesture={pointerId:42,kind:'move'};",c);
for(const type of ['pointermove','pointerup']){for(const listener of motionListeners[type]||[])listener({pointerId:99,target:{closest:()=>null},stopImmediatePropagation(){},preventDefault(){},clientX:10,clientY:10});assert.equal(vm.runInContext('canvasGesture.pointerId',c),42);}
vm.runInContext('cancelCanvasGesture({pointerId:99});',c);assert.equal(vm.runInContext('canvasGesture.pointerId',c),42);
vm.runInContext('cancelCanvasGesture({pointerId:42});',c);assert.equal(vm.runInContext('canvasGesture',c),null);
console.log('PASS Canvas ignores secondary pointer movement/release and cancellation, cancels the owning pointer.');
